function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
const state={name:'',stage:0,mapRound:0,points:{map:0,art:0,sim:0},mistakes:new Set(),placed:new Set(),archived:new Set(),selected:null,tool:'glove',solved:new Set(),log:[],rain:false,priorityMistake:false,finished:false,ignored:new Set(),avatar:{x:440,y:500},destination:null,focus:null,muted:false};
let audioContext,toastTimer,frame,lastFrame=0;
function sound(good=true){if(state.muted)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const t=audioContext.currentTime;[good?440:170,good?660:135].forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=good?'sine':'triangle';o.frequency.value=f;g.gain.setValueAtTime(.0001,t+i*.1);g.gain.exponentialRampToValueAtTime(.08,t+i*.1+.01);g.gain.exponentialRampToValueAtTime(.0001,t+i*.1+.22);o.connect(g);g.connect(audioContext.destination);o.start(t+i*.1);o.stop(t+i*.1+.23);});}catch{}}
function toast(message,good=true){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);sound(good);}
function total(){return state.points.map+state.points.art+state.points.sim;}
function progress(){return Math.round((state.placed.size+state.archived.size+state.solved.size)/19*100);}
function hud(){return `<div class="hud"><div><div class="agent-name">EJEN <strong>${escapeHTML(state.name.toUpperCase())}</strong> <span aria-hidden="true"> / </span> OPERASI CODE RED</div><div class="progress-track" role="progressbar" aria-label="Kemajuan misi" aria-valuenow="${progress()}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${progress()}%"></div></div><div class="steps"><span class="${state.stage===1?'active':''}">01 / JEJAK TAMADUN</span><span class="${state.stage===2?'active':''}">02 / ARKIB KHAZANAH</span><span class="${state.stage===3?'active':''}">03 / OPERASI WARISAN</span></div></div><div class="score">${total()}<small> / 100</small></div></div>`;}
