const hero=`<svg viewBox="0 0 600 620" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><pattern id="heroGrid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#647c6e" stroke-opacity=".18"/></pattern><linearGradient id="pyr" x2="1" y2="1"><stop stop-color="#f1da9b"/><stop offset="1" stop-color="#ac9161"/></linearGradient></defs><rect width="600" height="620" fill="#c6cbb0"/><rect width="600" height="620" fill="url(#heroGrid)"/><circle cx="320" cy="290" r="214" fill="none" stroke="#68857a" stroke-dasharray="4 10"/><circle cx="320" cy="290" r="165" fill="#b6bea0" stroke="#76917c"/><path d="M0 470Q170 370 300 430T600 400V620H0" fill="#a1b393"/><path d="M365 100Q250 180 400 275T355 535" fill="none" stroke="#689b97" stroke-width="36"/><path d="M365 100Q250 180 400 275T355 535" fill="none" stroke="#acd1bc" stroke-width="3" stroke-dasharray="8 12"/><path d="M70 388L230 170L360 388Z" fill="url(#pyr)"/><path d="M230 170L245 388H360Z" fill="#92774d"/><path d="M85 367H243M104 343H240M123 318H237M142 293H234M163 265H233M181 240H231" stroke="#b19360" stroke-width="2"/><path d="M343 412h205v-40H343zm25-40h155v-43H368zm27-43h101v-45H395zm27-45h48v-42h-48z" fill="#dfc17f" stroke="#927e52" stroke-width="3"/><path d="M428 410V290h33v120" fill="#8b7853"/><g transform="translate(140 420) rotate(-12)"><rect width="120" height="90" rx="15" fill="#b78660" stroke="#825d46" stroke-width="4"/><path d="M20 20l10 8-10 8m22-16 10 8-10 8m22-16 10 8-10 8M20 50l10 8-10 8m22-16 10 8-10 8m22-16 10 8-10 8" fill="none" stroke="#604d3c" stroke-width="5"/></g><g transform="translate(440 182)"><circle r="27" fill="#253e37"/><path d="M-9 0l6 7 14-16" fill="none" stroke="#f2d488" stroke-width="4"/><circle r="37" fill="none" stroke="#466754"/></g><path d="M60 80h30m-15-15v30M508 465h30m-15-15v30" stroke="#436456" stroke-width="2"/></svg>`;
function landing(){state.stage=0;app.innerHTML=`<section class="landing"><div><p class="eyebrow"><span class="dot"></span>PANGGILAN SULIT UNTUK EJEN BAHARU</p><h1>MASA LALU.<br>MISI <span class="red">KITA.</span></h1><p class="lead">Empat tamadun. Khazanah yang tidak ternilai.<br>Jejaki asal usulnya dan lindungi tinggalannya sebelum terlambat.</p><form id="start-form"><label class="name-label" for="name">Nama murid / identiti ejen</label><div class="form-row"><input id="name" name="name" placeholder="Masukkan nama anda" maxlength="40" required autocomplete="given-name"><button class="primary" type="submit">Terima misi ↗</button></div></form><p class="micro">Nama kekal dalam sesi ini sahaja. Sedia untuk bertindak?</p><div class="tags"><span>◉ PETA INTERAKTIF</span><span>◇ ARKIB ARTIFAK</span><span>⌖ SIMULASI LAPANGAN</span></div></div><div class="hero-art"><div class="hero-label">FAIL OPERASI / MH–005<br>STATUS: CODE RED</div>${hero}<div class="hero-stamp"><b>05</b><p><strong>Tamadun Awal Dunia</strong>Sejarah Tingkatan 1 · Misi berpandukan Bab 5</p></div></div></section>`;$('#start-form').onsubmit=e=>{e.preventDefault();const n=$('#name').value.trim();if(!n){$('#name').setCustomValidity('Sila masukkan nama murid.');$('#name').reportValidity();return;}state.name=n;sound();codeRedIntro();};$('#name').oninput=()=>$('#name').setCustomValidity('');}

let introTimer;
function codeRedIntro(){
  clearTimeout(introTimer);
  let remaining=10,closed=false;
  const messages=[
    ['RALAT 005 / SAMBUNGAN TERPUTUS','Isyarat asing dikesan dalam arkib tamadun.'],
    ['AMARAN / ARKIB TERANCAM','Koordinat tamadun telah dikacau. Identiti khazanah tidak dapat disahkan.'],
    ['PANGGILAN KECEMASAN','Ejen '+state.name+', pusat operasi memerlukan bantuan anda sekarang.'],
    ['LALUAN KECEMASAN DITEMUI','Memindahkan fail misi ke saluran selamat…']
  ];
  app.innerHTML='<section class="code-intro" aria-label="Pembukaan sinematik Code Red"><div class="intro-grid" aria-hidden="true"></div><div class="intro-top"><span>MH / SALURAN SULIT</span><span class="intro-live">● AMARAN AKTIF</span></div><div class="intro-content"><p class="eyebrow">TRANSMISI TERGANGGU</p><h1 class="error-title" data-text="CODE ERROR">CODE ERROR</h1><p class="intro-subtitle">ARKIB KHAZANAH DALAM BAHAYA</p><div class="countdown-box"><span>SALURAN AKAN DIKUNCI DALAM</span><strong id="intro-clock" aria-hidden="true">00:10</strong><small>KIRA DETIK OPERASI</small></div><div class="intro-terminal" role="status" aria-live="polite"><b id="intro-status"></b><p id="intro-message"></p></div><div class="intro-meter" aria-hidden="true"><i id="intro-meter-fill"></i></div><p class="intro-agent">EJEN <strong>'+escapeHTML(state.name.toUpperCase())+'</strong> · MENUNGGU ARAHAN</p></div><div class="intro-bottom"><span>SIMULASI OPERASI · FAIL MH–005</span><button id="skip-intro" class="quiet">Langkau intro →</button></div></section>';
  scrollTop();
  function finish(){if(closed)return;closed=true;clearTimeout(introTimer);sound(true);briefing();scrollTop();$('#begin').focus();}
  $('#skip-intro').onclick=finish;
  function tick(){
    if(closed||!$('#intro-clock'))return;
    $('#intro-clock').textContent='00:'+String(remaining).padStart(2,'0');
    $('#intro-meter-fill').style.width=((10-remaining)*10)+'%';
    const index=remaining>7?0:remaining>4?1:remaining>2?2:3;
    $('#intro-status').textContent=messages[index][0];
    $('#intro-message').textContent=messages[index][1];
    if(remaining===0){introTimer=setTimeout(finish,700);return;}
    sound(false);
    remaining--;
    introTimer=setTimeout(tick,1000);
  }
  tick();
}

function briefing(){app.innerHTML=`<section class="panel brief"><p class="eyebrow">IDENTITI DISAHKAN / AKSES DIBERIKAN</p><h1>Selamat datang<br><span class="red">Ejen ${escapeHTML(state.name)}</span></h1><p class="alert">RED CODE: selesaikan misi kita dan selamatkan khazanah</p><div class="mission-cards"><section><b>01 · JEJAK</b><h3>Peta tamadun</h3><p>Letakkan tamadun dan sungai pada lokasi geografi.</p></section><section><b>02 · KENAL PASTI</b><h3>Arkib khazanah</h3><p>Pulangkan setiap tinggalan kepada tamadunnya.</p></section><section><b>03 · BERTINDAK</b><h3>Selamatkan tapak</h3><p>Bergerak, siasat dan gunakan peralatan dengan bijak.</p></section></div><button id="begin" class="primary">Mulakan operasi →</button><p class="micro">Tiada had masa. Perhatikan petunjuk dan fikir sebelum bertindak.</p></section>`;$('#begin').onclick=()=>{state.stage=1;renderMap();scrollTop();};}
