let mapOrder=[],pinOrder=[],mapFeedback='Pilih label dan seret ke pin yang sepadan. Tiada jawapan diberi pada pin.';
function renderMap(){if(!mapOrder.length){mapOrder=shuffle(mapItems.filter(i=>i.round===state.mapRound));pinOrder=shuffle(mapOrder);}const round=mapItems.filter(i=>i.round===state.mapRound),done=round.every(i=>state.placed.has(i.id));app.innerHTML=hud()+heading('MISI 01 / JEJAK TAMADUN',state.mapRound?'Jejaki nadi kehidupan.':'Empat tamadun. Satu peta.',state.mapRound?'Kenal pasti enam sungai. Bezakan Tigris dengan Euphrates serta Huang He dengan Yangtze.':'Seret nama tamadun ke pin lokasinya. Perhatikan benua, pantai dan lembah sungai.',`PUSINGAN ${state.mapRound+1} / 2`)+`<div class="map-layout"><section class="map-card"><div class="map-toolbar"><strong>ATLAS LAPANGAN / AFRIKA–ASIA</strong><button id="zoom">＋ Zum peta</button></div><div class="map-scroll"><div class="map-world"><img src="data:image/svg+xml;base64," alt="Peta geografi Afrika timur laut hingga Asia timur dengan garis pantai, sempadan moden dan enam sungai ditanda biru" draggable="false">${pinOrder.map((i,n)=>`<button class="pin ${state.placed.has(i.id)?'done':''}" data-pin="${i.id}" style="left:${(i.lon-15)*.9}%;top:${(57-i.lat)*10/5.2}%" aria-label="Pin ${n+1}${state.placed.has(i.id)?': '+i.name:''}">${state.placed.has(i.id)?'✓':n+1}<span class="pin-label">${i.name}</span></button>`).join('')}</div></div><div class="map-caption">Biru: aliran sungai · Utara ↑ · Pin menandakan kawasan rujukan, bukan keseluruhan wilayah tamadun. Leret peta / zum untuk lokasi berdekatan.</div></section><aside class="panel label-bank"><p class="eyebrow">BEKALAN INTEL</p><h3>${round.filter(i=>!state.placed.has(i.id)).length} label belum diletakkan</h3><p>Seret label, atau ketik label kemudian pin. Label diacak setiap sesi.</p><div class="labels">${mapOrder.map(i=>`<button class="drag-label ${state.placed.has(i.id)?'done':''}" data-label="${i.id}" ${state.placed.has(i.id)?'disabled':''}>${state.placed.has(i.id)?'✓':'⠿'} ${i.name}</button>`).join('')}</div></aside></div><div class="feedback" role="status">${escapeHTML(mapFeedback)}</div><div class="next-row"><button class="primary" id="map-next" ${done?'':'disabled'}>${state.mapRound?'Buka arkib khazanah':'Teruskan: jejaki sungai'} →</button></div>`;
$('#zoom').onclick=()=>{const z=$('.map-world').classList.toggle('zoomed');$('#zoom').textContent=z?'− Kecilkan':'＋ Zum peta';};
document.querySelectorAll('[data-label]').forEach(el=>{el.onclick=()=>selectLabel(el.dataset.label);el.onpointerdown=e=>startDrag(e,el);});
document.querySelectorAll('[data-pin]').forEach(el=>el.onclick=()=>placeLabel(state.selected,el.dataset.pin));
$('#map-next').onclick=()=>{if(!done)return;state.selected=null;if(!state.mapRound){state.mapRound=1;mapOrder=[];mapFeedback='Perhatikan sungai di timur dan barat. Gunakan zum jika dua pin berdekatan.';renderMap();}else{state.stage=2;renderArtifacts();}scrollTop();};}
function selectLabel(id){if(state.placed.has(id))return;state.selected=id;document.querySelectorAll('[data-label]').forEach(e=>e.classList.toggle('selected',e.dataset.label===id));}
function placeLabel(id,pin){if(!id){toast('Pilih satu label terlebih dahulu.',false);return;}if(state.placed.has(id))return;if(id!==pin){state.mistakes.add(id);$('.feedback').textContent='Lokasi belum tepat. Perhatikan kedudukan sungai, pantai dan benua; cuba semula. Nilai label ini kini 2/3 markah.';toast('Semak lokasi dan cuba semula.',false);return;}state.placed.add(id);state.points.map+=state.mistakes.has(id)?2:3;state.selected=null;mapFeedback=mapItems.find(i=>i.id===id).fact;toast('Lokasi disahkan. Intel berjaya dipulihkan.');renderMap();}
function startDrag(e,el){if(e.button!==0||state.placed.has(el.dataset.label))return;selectLabel(el.dataset.label);let moved=false,ghost;const sx=e.clientX,sy=e.clientY;el.setPointerCapture(e.pointerId);const move=ev=>{if(Math.hypot(ev.clientX-sx,ev.clientY-sy)>7)moved=true;if(!moved)return;if(!ghost){ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent=el.textContent;document.body.appendChild(ghost);}ghost.style.left=(ev.clientX+8)+'px';ghost.style.top=(ev.clientY-50)+'px';};const end=ev=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',cancel);ghost?.remove();if(moved){const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-pin]');if(target)placeLabel(el.dataset.label,target.dataset.pin);else toast('Lepaskan label pada pin bulat di peta.',false);}};const cancel=()=>{ghost?.remove();el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',cancel);};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);el.addEventListener('pointercancel',cancel);}
function artSVG(type){const start='<svg viewBox="0 0 240 190" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><ellipse cx="120" cy="159" rx="82" ry="13" fill="#968f7040"/>';const drawings={tablet:'<g transform="rotate(-9 120 95)"><rect x="53" y="31" width="138" height="126" rx="20" fill="#b88963" stroke="#825f49" stroke-width="4"/><rect x="64" y="42" width="116" height="102" rx="12" fill="#c29970"/><g stroke="#715643" stroke-width="4" fill="none"><path d="M78 58l12 7-12 7m27-14 12 7-12 7m27-14 12 7-12 7m27-14 8 7-8 7M78 87l12 7-12 7m27-14 12 7-12 7m27-14 12 7-12 7M78 116l12 7-12 7m27-14 12 7-12 7m27-14 12 7-12 7m27-14 8 7-8 7"/></g></g>',pyramid:'<path d="M30 153L120 28L212 153Z" fill="#d6b16a"/><path d="M120 28L133 153H212Z" fill="#9b784c"/><path d="M44 134h87M58 114h71M73 93h54M86 73h39M100 53h23" stroke="#aa8954" stroke-width="2"/><rect x="139" y="130" width="13" height="23" fill="#665b45"/>',city:'<path d="M32 65L131 23L219 73L123 134Z" fill="#c8b18b"/><g fill="#ae8c66" stroke="#776b4f" stroke-width="2"><path d="M41 70V52l25-12 21 12v18L63 83Z"/><path d="M95 45V28l25-10 21 12v18l-25 12Z"/><path d="M151 67V49l25-11 22 13v18l-25 12Z"/><path d="M46 124v-18l25-12 22 13v18l-25 12Z"/><path d="M152 125v-18l25-12 22 13v18l-25 12Z"/></g><path d="M93 78l30-15 29 16-29 17Z" fill="#497f7d" stroke="#ebe3c6" stroke-width="6"/><path d="M33 90l91 51 88-46M122 151v18M90 63l76 44" fill="none" stroke="#eee5c8" stroke-width="6"/><path d="M122 143v25" stroke="#548e8c" stroke-width="3"/>',silk:'<path d="M70 43Q123 17 178 43v103Q125 124 70 150Z" fill="#a75447" stroke="#744b3e" stroke-width="3"/><ellipse cx="70" cy="97" rx="16" ry="55" fill="#dbc19a"/><ellipse cx="70" cy="97" rx="7" ry="43" fill="#ad9473"/><path d="M105 43v98m30-103v97m29-95v102" stroke="#eac580" stroke-width="3"/><path d="M90 60q40-12 88 0M89 85q40-12 89 0M88 110q40-12 90 0" stroke="#eac580" stroke-width="3"/><path d="M111 68l12 14-12 14-12-14Z" fill="#e7ca8d"/>'};return start+drawings[type]+'</svg>';}
